-- STEP 18.12 — Regression & Acceptance verification
-- READ-ONLY. No schema/data changes.
-- Expected result before final acceptance: 64 / 64 PASS.
with checks(check_no,check_name,status,details) as (
  select 1,'core_journal_tables',case when to_regclass('public.accounting_journal_entries') is not null and to_regclass('public.accounting_journal_lines') is not null then 'PASS' else 'FAIL' end,'Journal header/line tables exist.'
  union all select 2,'durable_outbox_exists',case when to_regclass('public.please_accounting_outbox') is not null then 'PASS' else 'FAIL' end,'STEP 17 durable financial outbox exists.'
  union all select 3,'external_event_log_exists',case when to_regclass('public.accounting_external_events') is not null then 'PASS' else 'FAIL' end,'CAL external event log exists.'
  union all select 4,'posting_rules_exist',case when to_regclass('public.accounting_posting_rules') is not null then 'PASS' else 'FAIL' end,'Posting-rule registry exists.'
  union all select 5,'integration_registry_exists',case when to_regclass('public.accounting_integration_contracts') is not null then 'PASS' else 'FAIL' end,'STEP 18.11 canonical contract registry exists.'
  union all select 6,'integration_contract_count',case when (select count(*) from public.accounting_integration_contracts where active)=27 then 'PASS' else 'FAIL' end,'27 active contracts expected.'
  union all select 7,'financial_contract_count',case when (select count(*) from public.accounting_integration_contracts where active and route='FINANCIAL_OUTBOX')=22 then 'PASS' else 'FAIL' end,'22 financial STEP 17 routes expected.'
  union all select 8,'domain_contract_count',case when (select count(*) from public.accounting_integration_contracts where active and route='DOMAIN_EVENT_ONLY')=5 then 'PASS' else 'FAIL' end,'5 compliance domain-only routes expected.'
  union all select 9,'integration_health_callable',case when to_regprocedure('public.accounting_integration_health()') is not null and jsonb_typeof(public.accounting_integration_health())='object' then 'PASS' else 'FAIL' end,'Integration Health RPC is callable.'
  union all select 10,'integration_zero_blockers',case when coalesce((public.accounting_integration_health()->>'blockers')::int,999)=0 then 'PASS' else 'FAIL' end,'Integration Health has zero BLOCKER exceptions.'
  union all select 11,'no_missing_durable_events',case when not exists(select 1 from public.accounting_expected_financial_events e left join public.please_accounting_outbox o on o.event_key=e.event_key where o.id is null) then 'PASS' else 'FAIL' end,'Every current source fact has its durable event.'
  union all select 12,'no_dead_letter',case when not exists(select 1 from public.please_accounting_outbox where status='DEAD_LETTER') then 'PASS' else 'FAIL' end,'No exhausted accounting event.'
  union all select 13,'no_retrying_events',case when not exists(select 1 from public.please_accounting_outbox where status='RETRY') then 'PASS' else 'FAIL' end,'No event waiting for retry.'
  union all select 14,'no_processing_events',case when not exists(select 1 from public.please_accounting_outbox where status='PROCESSING') then 'PASS' else 'FAIL' end,'No event stranded in PROCESSING.'
  union all select 15,'no_pending_events',case when not exists(select 1 from public.please_accounting_outbox where status='PENDING') then 'PASS' else 'FAIL' end,'Queue is drained at acceptance time.'
  union all select 16,'posted_have_external_event',case when not exists(select 1 from public.please_accounting_outbox where status='POSTED' and cal_event_id is null) then 'PASS' else 'FAIL' end,'POSTED events link to CAL external events.'
  union all select 17,'posted_have_journal',case when not exists(select 1 from public.please_accounting_outbox where status='POSTED' and cal_journal_entry_id is null) then 'PASS' else 'FAIL' end,'POSTED events link to journals.'
  union all select 18,'posted_journals_are_posted',case when not exists(select 1 from public.please_accounting_outbox o left join public.accounting_journal_entries j on j.id=o.cal_journal_entry_id where o.status='POSTED' and (j.id is null or j.status<>'POSTED')) then 'PASS' else 'FAIL' end,'Linked journals are POSTED.'
  union all select 19,'ignored_have_no_journal',case when not exists(select 1 from public.please_accounting_outbox where status='IGNORED' and cal_journal_entry_id is not null) then 'PASS' else 'FAIL' end,'IGNORED events never create journals.'
  union all select 20,'event_keys_unique',case when (select count(*) from public.please_accounting_outbox)=(select count(distinct event_key) from public.please_accounting_outbox) then 'PASS' else 'FAIL' end,'Durable event keys are unique.'
  union all select 21,'expected_event_keys_unique',case when (select count(*) from public.accounting_expected_financial_events)=(select count(distinct event_key) from public.accounting_expected_financial_events) then 'PASS' else 'FAIL' end,'Expected source-event keys are unique.'
  union all select 22,'no_unregistered_outbox_types',case when not exists(select 1 from public.please_accounting_outbox o where upper(coalesce(o.source_system,'PLEASE'))='PLEASE' and not exists(select 1 from public.accounting_integration_contracts c where c.active and c.route='FINANCIAL_OUTBOX' and c.event_type=o.event_type)) then 'PASS' else 'FAIL' end,'Every financial outbox type is registered.'
  union all select 23,'no_source_contract_mismatch',case when not exists(select 1 from public.please_accounting_outbox o join public.accounting_integration_contracts c on c.active and c.route='FINANCIAL_OUTBOX' and c.event_type=o.event_type where coalesce(o.source_table,'')<>c.source_table) then 'PASS' else 'FAIL' end,'Outbox source tables match canonical contracts.'
  union all select 24,'compliance_not_in_financial_outbox',case when not exists(select 1 from public.please_accounting_outbox where event_type in ('GIFI_WORKING_PAPER_CREATED','COMPLIANCE_OBLIGATION_CREATED','COMPLIANCE_APPROVAL_RECORDED','COMPLIANCE_EVIDENCE_RECORDED','ACCOUNTANT_PACKAGE_CREATED')) then 'PASS' else 'FAIL' end,'Compliance domain events do not enter financial outbox.'
  union all select 25,'domain_event_log_exists',case when to_regclass('public.please_domain_events') is not null then 'PASS' else 'FAIL' end,'Immutable non-financial domain event log exists.'
  union all select 26,'outbox_contract_guard',case when exists(select 1 from pg_trigger where tgname='trg_step18_11_outbox_contract_guard' and not tgisinternal) then 'PASS' else 'FAIL' end,'Financial outbox contract guard is attached.'
  union all select 27,'posted_journal_immutability',case when exists(select 1 from pg_trigger where tgname='trg_accounting_prevent_posted_journal_mutation' and not tgisinternal) then 'PASS' else 'FAIL' end,'Posted journal immutability trigger exists.'
  union all select 28,'all_posted_journals_balanced',case when not exists(select 1 from public.accounting_journal_entries j join public.accounting_journal_lines l on l.journal_entry_id=j.id where j.status='POSTED' group by j.id having abs(sum(l.debit)-sum(l.credit))>0.004) then 'PASS' else 'FAIL' end,'Every POSTED journal balances independently.'
  union all select 29,'posted_journals_have_two_lines',case when not exists(select 1 from public.accounting_journal_entries j left join public.accounting_journal_lines l on l.journal_entry_id=j.id where j.status='POSTED' group by j.id having count(l.id)<2) then 'PASS' else 'FAIL' end,'Every POSTED journal has at least two lines.'
  union all select 30,'no_orphan_journal_lines',case when not exists(select 1 from public.accounting_journal_lines l left join public.accounting_journal_entries j on j.id=l.journal_entry_id where j.id is null) then 'PASS' else 'FAIL' end,'No orphan journal lines.'
  union all select 31,'global_trial_balance_balanced',case when abs(coalesce((select sum(l.debit-l.credit) from public.accounting_journal_lines l join public.accounting_journal_entries j on j.id=l.journal_entry_id where j.status='POSTED'),0))<=0.004 then 'PASS' else 'FAIL' end,'Global POSTED Trial Balance difference is zero.'
  union all select 32,'inventory_core_exists',case when to_regclass('public.accounting_inventory_items') is not null and to_regclass('public.accounting_inventory_movements') is not null and to_regclass('public.accounting_inventory_balances') is not null then 'PASS' else 'FAIL' end,'Inventory perpetual subledger exists.'
  union all select 33,'inventory_control_functions',case when to_regprocedure('public.accounting_inventory_gl_balance(date)') is not null and to_regprocedure('public.accounting_inventory_subledger_value()') is not null then 'PASS' else 'FAIL' end,'Inventory GL/subledger control RPCs exist.'
  union all select 34,'inventory_reconciles',case when abs(coalesce(public.accounting_inventory_gl_balance(current_date),0)-coalesce(public.accounting_inventory_subledger_value(),0))<=0.02 then 'PASS' else 'FAIL' end,'Inventory subledger equals GL 1600.'
  union all select 35,'fixed_asset_core_exists',case when to_regclass('public.accounting_fixed_assets') is not null and to_regclass('public.accounting_fixed_asset_depreciation_runs') is not null then 'PASS' else 'FAIL' end,'Fixed Asset register/depreciation tables exist.'
  union all select 36,'fixed_asset_control_functions',case when to_regprocedure('public.accounting_fixed_asset_gross_gl_balance(date)') is not null and to_regprocedure('public.accounting_fixed_asset_accum_gl_balance(date)') is not null and to_regprocedure('public.accounting_fixed_asset_gross_subledger_value()') is not null and to_regprocedure('public.accounting_fixed_asset_accum_subledger_value(date)') is not null then 'PASS' else 'FAIL' end,'Fixed Asset GL/subledger control RPCs exist.'
  union all select 37,'fixed_asset_gross_reconciles',case when abs(public.accounting_fixed_asset_gross_gl_balance(current_date)-public.accounting_fixed_asset_gross_subledger_value())<=0.02 then 'PASS' else 'FAIL' end,'Fixed Asset gross subledger equals GL 1500.'
  union all select 38,'fixed_asset_accum_reconciles',case when abs(public.accounting_fixed_asset_accum_gl_balance(current_date)-public.accounting_fixed_asset_accum_subledger_value(current_date))<=0.02 then 'PASS' else 'FAIL' end,'Accumulated depreciation subledger equals GL 1510.'
  union all select 39,'ar_core_exists',case when to_regclass('public.accounting_invoices') is not null and to_regclass('public.accounting_payments') is not null and to_regclass('public.accounting_credit_notes') is not null and to_regclass('public.accounting_customer_refunds') is not null then 'PASS' else 'FAIL' end,'A/R, payment, credit-note and refund ledgers exist.'
  union all select 40,'ap_core_exists',case when to_regclass('public.accounting_supplier_bills') is not null and to_regclass('public.accounting_supplier_payments') is not null then 'PASS' else 'FAIL' end,'Supplier Bills and A/P payment ledgers exist.'
  union all select 41,'expense_core_exists',case when to_regclass('public.accounting_expense_claims') is not null and to_regclass('public.accounting_expense_reimbursements') is not null then 'PASS' else 'FAIL' end,'Advanced Expense workflow tables exist.'
  union all select 42,'banking_core_exists',case when to_regclass('public.accounting_bank_reconciliations') is not null and to_regclass('public.accounting_bank_transactions') is not null and to_regclass('public.accounting_bank_matches') is not null then 'PASS' else 'FAIL' end,'Treasury/Bank Reconciliation tables exist.'
  union all select 43,'closed_bank_recons_balance',case when not exists(select 1 from public.accounting_bank_reconciliations where status='CLOSED' and abs(coalesce(difference,0))>0.01) then 'PASS' else 'FAIL' end,'Every CLOSED bank reconciliation has zero control difference.'
  union all select 44,'payroll_core_exists',case when to_regclass('public.accounting_payroll_employees') is not null and to_regclass('public.accounting_payroll_runs') is not null and to_regclass('public.accounting_payroll_remittances') is not null then 'PASS' else 'FAIL' end,'Payroll employee/run/remittance tables exist.'
  union all select 45,'payroll_t4_exists',case when to_regclass('public.accounting_payroll_t4_working_papers') is not null then 'PASS' else 'FAIL' end,'T4 working-paper table exists.'
  union all select 46,'period_close_core_exists',case when to_regclass('public.accounting_period_close_checklist') is not null and to_regclass('public.accounting_period_close_snapshots') is not null and to_regclass('public.accounting_period_adjustments') is not null then 'PASS' else 'FAIL' end,'Advanced Period Close tables exist.'
  union all select 47,'closed_periods_have_locks',case when not exists(select 1 from public.accounting_fiscal_periods p where p.status='CLOSED' and not exists(select 1 from public.accounting_period_locks l where l.period_start=p.period_start and l.period_end=p.period_end)) then 'PASS' else 'FAIL' end,'Every CLOSED period has its posting lock.'
  union all select 48,'no_overlapping_fiscal_periods',case when not exists(select 1 from public.accounting_fiscal_periods a join public.accounting_fiscal_periods b on a.id<b.id and a.period_start<=b.period_end and a.period_end>=b.period_start) then 'PASS' else 'FAIL' end,'Fiscal periods do not overlap.'
  union all select 49,'no_overlapping_period_locks',case when not exists(select 1 from public.accounting_period_locks a join public.accounting_period_locks b on a.id<b.id and a.period_start<=b.period_end and a.period_end>=b.period_start) then 'PASS' else 'FAIL' end,'Posting locks do not overlap.'
  union all select 50,'period_open_assert_exists',case when to_regprocedure('public.accounting_assert_period_open(date,text)') is not null then 'PASS' else 'FAIL' end,'Closed-period boundary assertion exists.'
  union all select 51,'compliance_core_exists',case when to_regclass('public.accounting_compliance_settings') is not null and to_regclass('public.accounting_compliance_obligations') is not null and to_regclass('public.accounting_compliance_approvals') is not null and to_regclass('public.accounting_filing_evidence') is not null then 'PASS' else 'FAIL' end,'Accountant & Compliance core tables exist.'
  union all select 52,'gifi_core_exists',case when to_regclass('public.accounting_gifi_account_mappings') is not null and to_regclass('public.accounting_gifi_working_papers') is not null and to_regclass('public.accounting_gifi_working_paper_lines') is not null then 'PASS' else 'FAIL' end,'GIFI mapping/working-paper tables exist.'
  union all select 53,'gifi_all_active_accounts_mapped',case when not exists(select 1 from public.accounting_accounts a where a.active and not exists(select 1 from public.accounting_gifi_account_mappings m join public.accounting_gifi_codes g on g.code=m.gifi_code and g.active where m.account_id=a.id)) then 'PASS' else 'FAIL' end,'Every active GL account has an active GIFI mapping.'
  union all select 54,'accountant_package_core_exists',case when to_regclass('public.accounting_accountant_packages') is not null and to_regprocedure('public.accounting_build_accountant_package_snapshot(integer,uuid)') is not null then 'PASS' else 'FAIL' end,'Immutable Accountant Package capability exists.'
  union all select 55,'accountant_package_hashes_present',case when not exists(select 1 from public.accounting_accountant_packages where snapshot_sha256 is null or length(snapshot_sha256)<>64) then 'PASS' else 'FAIL' end,'Every existing Accountant Package carries SHA-256 evidence.'
  union all select 56,'compliance_domain_triggers_present',case when exists(select 1 from pg_trigger where tgname='trg_step18_11_gifi_domain_event' and not tgisinternal) and exists(select 1 from pg_trigger where tgname='trg_step18_11_obligation_domain_event' and not tgisinternal) and exists(select 1 from pg_trigger where tgname='trg_step18_11_approval_domain_event' and not tgisinternal) and exists(select 1 from pg_trigger where tgname='trg_step18_11_evidence_domain_event' and not tgisinternal) and exists(select 1 from pg_trigger where tgname='trg_step18_11_package_domain_event' and not tgisinternal) then 'PASS' else 'FAIL' end,'All five compliance domain-event producers are attached.'
  union all select 57,'financial_producers_present',case when exists(select 1 from pg_trigger where tgname='trg_step17_accounting_invoice_event' and not tgisinternal) and exists(select 1 from pg_trigger where tgname='trg_step17_accounting_payment_event' and not tgisinternal) and exists(select 1 from pg_trigger where tgname='trg_step17_accounting_provider_payment_event' and not tgisinternal) then 'PASS' else 'FAIL' end,'Core PLEASE financial producers remain attached.'
  union all select 58,'rule_contracts_have_rules',case when not exists(select 1 from public.accounting_integration_contracts c where c.active and c.route='FINANCIAL_OUTBOX' and c.posting_mode='RULE' and not exists(select 1 from public.accounting_posting_rules r where r.source_system='PLEASE' and r.event_type=c.event_type and r.enabled)) then 'PASS' else 'FAIL' end,'Every RULE-driven financial contract has an enabled posting rule.'
  union all select 59,'registered_producers_resolve',case when not exists(select 1 from public.accounting_integration_contracts c where c.active and ((c.producer_kind='TRIGGER' and not exists(select 1 from pg_trigger t where t.tgname=c.producer_name and not t.tgisinternal)) or (c.producer_kind='RPC' and not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname=c.producer_name)))) then 'PASS' else 'FAIL' end,'Every registered event producer exists.'
  union all select 60,'structural_integration_exceptions_zero',case when not exists(select 1 from public.accounting_integration_exceptions(5000) where issue_code in ('SOURCE_TABLE_MISSING','PRODUCER_MISSING','POSTING_RULE_MISSING','UNREGISTERED_OUTBOX_EVENT','SOURCE_CONTRACT_MISMATCH','MISSING_DURABLE_EVENT','POSTED_WITHOUT_JOURNAL')) then 'PASS' else 'FAIL' end,'No structural/coverage Integration Health blockers.'
  union all select 61,'gifi_loss_sign_mapping',case when exists(select 1 from public.accounting_gifi_account_mappings m join public.accounting_accounts a on a.id=m.account_id join public.accounting_gifi_codes g on g.code=m.gifi_code and g.active where a.code='6300' and m.gifi_code='8210' and m.sign_multiplier=-1) then 'PASS' else 'FAIL' end,'Loss on disposal maps to GIFI 8210 with negative multiplier.'
  union all select 62,'accum_dep_gifi_mapping',case when exists(select 1 from public.accounting_gifi_account_mappings m join public.accounting_accounts a on a.id=m.account_id join public.accounting_gifi_codes g on g.code=m.gifi_code and g.active where a.code='1510' and m.gifi_code='1741' and m.sign_multiplier=1) then 'PASS' else 'FAIL' end,'Accumulated depreciation maps to GIFI 1741.'
  union all select 63,'no_future_closed_period',case when not exists(select 1 from public.accounting_fiscal_periods where status='CLOSED' and period_end>current_date) then 'PASS' else 'FAIL' end,'No future fiscal period is CLOSED.'
  union all select 64,'release_database_ready',case when coalesce((public.accounting_integration_health()->>'blockers')::int,999)=0 and not exists(select 1 from public.please_accounting_outbox where status in ('PENDING','PROCESSING','RETRY','DEAD_LETTER')) and abs(coalesce((select sum(l.debit-l.credit) from public.accounting_journal_lines l join public.accounting_journal_entries j on j.id=l.journal_entry_id where j.status='POSTED'),0))<=0.004 then 'PASS' else 'FAIL' end,'Final database gate: integration clean, queue drained, Trial Balance balanced.'
)
select * from checks order by check_no;
